script:
html { scroll-behavior: smooth; }
::selection { background: #FF4D00; color: #FFFFFF; }

html.rv-js .rv-rise { opacity: 0; transform: translateY(22px); }
html.rv-js .rv-rise.rv-in {
  opacity: 1; transform: none;
  transition: opacity 0.85s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}
html.rv-js .rv-d1.rv-in { transition-delay: 0.12s; }
html.rv-js .rv-d2.rv-in { transition-delay: 0.24s; }

.rv-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 2px;
  transition: background-size 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
.rv-ul:hover { background-size: 100% 2px; }

.rv-btn { transition: background-color 0.25s ease, transform 0.25s ease; }
.rv-btn:hover { background-color: #FF4D00; transform: translateY(-2px); }
.rv-btn-o { transition: background-color 0.25s ease, color 0.25s ease,
  border-color 0.25s ease, transform 0.25s ease; }
.rv-btn-o:hover { background-color: #17181B; border-color: #17181B;
  color: #F3F2EE; transform: translateY(-2px); }

.rv-card { position: relative; top: 0;
  transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s ease, border-color 0.35s ease; }
.rv-card:hover { border-color: #17181B;
  box-shadow: 0 18px 40px rgba(23, 24, 27, 0.12);
  transform: translateY(-5px); }
.rv-card .rv-arrow { transition: transform 0.35s ease, color 0.25s ease; }
.rv-card:hover .rv-arrow { color: #FF4D00; transform: translateX(5px); }

.rv-chip { transition: background-color 0.25s ease, color 0.25s ease,
  border-color 0.25s ease; }
.rv-chip:hover { background-color: #17181B; border-color: #17181B; }
.rv-chip:hover p { color: #F3F2EE; }

.rv-es { transition: letter-spacing 0.3s ease; }

@keyframes rv-scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
html.rv-js .rv-ticker { animation: rv-scroll 28s linear infinite; }

@keyframes rv-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
html.rv-js .rv-blink { animation: rv-pulse 1.6s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  html.rv-js .rv-ticker, html.rv-js .rv-blink { animation: none; }
}
